--
-- Name: check_long_running_timers(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_long_running_timers(p_threshold_hours numeric) RETURNS TABLE(id integer, organisation_id integer, utilisateur_id integer, projet_id integer, start_time timestamp with time zone, utilisateur_email character varying, projet_nom character varying, client_nom character varying, duration_hours numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    te.id,
    te.organisation_id,
    te.utilisateur_id,
    te.projet_id,
    te.start_time,
    u.email AS utilisateur_email,
    p.nom AS projet_nom,
    c.nom AS client_nom,
    ROUND(EXTRACT(EPOCH FROM (NOW() - te.start_time)) / 3600, 2) AS duration_hours
  FROM time_entries te
  JOIN projets p
    ON p.id = te.projet_id
    AND p.organisation_id = te.organisation_id
  JOIN clients c
    ON c.id = p.client_id
    AND c.organisation_id = te.organisation_id
  LEFT JOIN utilisateurs u
    ON u.id = te.utilisateur_id
    AND u.organisation_id = te.organisation_id
  WHERE te.end_time IS NULL
    AND te.organisation_id IS NOT NULL
    AND te.start_time <= NOW() - (p_threshold_hours * INTERVAL '1 hour')
  ORDER BY te.start_time ASC;
$$;


