--
-- Name: cleanup_old_chat_sessions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_chat_sessions(retention_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM help_chat_sessions
  WHERE organisation_id = CAST(current_setting('app.current_organisation_id') AS INTEGER)
    AND last_activity_at < CURRENT_TIMESTAMP - INTERVAL '1 day' * retention_days;
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: compute_platform_funnel_counts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_platform_funnel_counts(p_days integer) RETURNS TABLE(signups bigint, onboarding_completed bigint, first_invoice bigint, checkout_started bigint, subscription_active bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH recent_events AS (
    SELECT organisation_id, event_name
    FROM analytics_events
    WHERE created_at >= NOW() - INTERVAL '1 day' * p_days
  )
  SELECT
    COUNT(*) FILTER (WHERE event_name = 'signup_completed') AS signups,
    COUNT(*) FILTER (WHERE event_name = 'onboarding_completed') AS onboarding_completed,
    COUNT(*) FILTER (WHERE event_name IN ('first_invoice_created', 'invoice_created')) AS first_invoice,
    COUNT(*) FILTER (WHERE event_name = 'checkout_started') AS checkout_started,
    COUNT(*) FILTER (WHERE event_name = 'subscription_active') AS subscription_active
  FROM recent_events;
$$;


--
-- Name: compute_revenue_truth_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_revenue_truth_snapshot() RETURNS TABLE(analytics_subscription_active bigint, db_pro_orgs bigint, analytics_first_invoices bigint, db_orgs_with_invoices bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (SELECT COUNT(DISTINCT organisation_id) FROM analytics_events WHERE event_name = 'subscription_active' AND created_at >= NOW() - INTERVAL '90 days'),
    (SELECT COUNT(*) FROM organisations WHERE plan_type = 'pro' OR subscription_status = 'active'),
    (SELECT COUNT(DISTINCT organisation_id) FROM analytics_events WHERE event_name IN ('first_invoice_created', 'invoice_created') AND created_at >= NOW() - INTERVAL '90 days'),
    (SELECT COUNT(DISTINCT organisation_id) FROM invoices);
$$;


--
-- Name: compute_time_to_first_invoice(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_time_to_first_invoice(p_days integer) RETURNS TABLE(avg_minutes numeric, sample_size bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    COALESCE(AVG(EXTRACT(EPOCH FROM (fi.first_invoice - sc.signup)) / 60), 0) AS avg_minutes,
    COUNT(*) AS sample_size
  FROM (
    SELECT organisation_id, MIN(created_at) AS signup
    FROM analytics_events
    WHERE event_name = 'signup_completed'
      AND created_at >= NOW() - INTERVAL '1 day' * p_days
    GROUP BY organisation_id
  ) sc
  JOIN (
    SELECT organisation_id, MIN(created_at) AS first_invoice
    FROM analytics_events
    WHERE event_name IN ('first_invoice_created', 'invoice_created')
      AND created_at >= NOW() - INTERVAL '1 day' * p_days
    GROUP BY organisation_id
  ) fi USING (organisation_id);
$$;


