--

CREATE FUNCTION public.enable_default_modules_for_new_org() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM set_config('app.current_organisation_id', NEW.id::text, true);

  INSERT INTO organisation_modules (organisation_id, module_key, is_active)
  VALUES
    (NEW.id, 'dashboard', true),
    (NEW.id, 'timesheet', true),
    (NEW.id, 'clients', true),
    (NEW.id, 'projects', true),
    (NEW.id, 'invoices', true),
    (NEW.id, 'reports', true),
    (NEW.id, 'kiosk_punch', true),
    (NEW.id, 'calcul_km', true),
    (NEW.id, 'kiosk_km', true),
    (NEW.id, 'estimates', true),
    (NEW.id, 'activity_intelligence', true),
    (NEW.id, 'billing_assistant', true)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_accounting_period_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_accounting_period_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  configured_count INTEGER;
  target_period accounting_periods%ROWTYPE;
BEGIN
  SELECT COUNT(*) INTO configured_count
  FROM accounting_periods
  WHERE organisation_id = NEW.organisation_id;

  IF configured_count = 0 THEN
    NEW.period_id := NULL;
    RETURN NEW;
  END IF;

  SELECT * INTO target_period
  FROM accounting_periods
  WHERE organisation_id = NEW.organisation_id
    AND NEW.entry_date BETWEEN starts_on AND ends_on
  ORDER BY starts_on DESC
  LIMIT 1;

  IF target_period.id IS NULL THEN
    RAISE EXCEPTION 'Aucune période comptable ne couvre la date %.', NEW.entry_date
      USING ERRCODE = '23514';
  END IF;

  IF target_period.status <> 'open' THEN
    RAISE EXCEPTION 'La période comptable couvrant la date % est fermée.', NEW.entry_date
      USING ERRCODE = '23514';
  END IF;

  NEW.period_id := target_period.id;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_ledger_entries_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_ledger_entries_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  maintenance_mode TEXT := COALESCE(current_setting('app.ledger_maintenance_mode', true), 'off');
  maintenance_actor TEXT := NULLIF(BTRIM(COALESCE(current_setting('app.ledger_maintenance_actor', true), '')), '');
  maintenance_reason TEXT := NULLIF(BTRIM(COALESCE(current_setting('app.ledger_maintenance_reason', true), '')), '');
BEGIN
  IF maintenance_mode <> 'on' THEN
    RAISE EXCEPTION 'ledger_entries est append-only: % interdit', TG_OP
      USING ERRCODE = 'P0001';
  END IF;

  IF maintenance_actor IS NULL OR maintenance_reason IS NULL THEN
    RAISE EXCEPTION 'maintenance ledger refusée: actor et reason sont obligatoires'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO ledger_maintenance_audit (
    ledger_entry_id,
    organisation_id,
    operation,
    actor,
    reason,
    database_user,
    previous_row
  )
  VALUES (
    OLD.id,
    OLD.organisation_id,
    TG_OP,
    maintenance_actor,
    maintenance_reason,
    CURRENT_USER,
    TO_JSONB(OLD)
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_ledger_entries_append_only(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_ledger_entries_append_only() IS 'Interdit UPDATE/DELETE sur ledger_entries sauf maintenance explicite avec actor et reason, puis journalise la mutation.';


--
-- Name: ensure_accounting_period_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_accounting_period_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE period_status VARCHAR(16);
BEGIN
  -- Le renversement conserve l’écriture d’origine et crée une nouvelle écriture datée.
  -- Cette transition de statut ne modifie pas la période historique.
  IF TG_OP = 'UPDATE' AND OLD.status = 'posted' AND NEW.status = 'reversed' THEN
    RETURN NEW;
  END IF;

  SELECT status INTO period_status
  FROM accounting_periods
  WHERE organisation_id = NEW.organisation_id
    AND NEW.entry_date BETWEEN starts_on AND ends_on
  ORDER BY starts_on DESC
  LIMIT 1;

  IF period_status IN ('closed', 'locked') THEN
    RAISE EXCEPTION 'La période comptable correspondant à cette date est fermée.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: get_help_search_suggestions(integer, text, character varying, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_help_search_suggestions(p_organisation_id integer, p_partial_query text, p_language character varying DEFAULT 'fr'::character varying, p_limit integer DEFAULT 10) RETURNS TABLE(suggestion character varying, type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT DISTINCT
    hsi.title as suggestion,
    'article'::VARCHAR(50) as type
  FROM help_search_index hsi
  WHERE hsi.organisation_id = p_organisation_id
    AND hsi.language = p_language
    AND hsi.title ILIKE '%' || p_partial_query || '%'
  ORDER BY hsi.title
  LIMIT p_limit;
END;
$$;


