--
-- Name: list_due_estimate_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_due_estimate_reminders() RETURNS TABLE(id integer, organisation_id integer, client_id integer, estimate_number character varying, status character varying, issue_date date, valid_until date, subtotal numeric, tax_total numeric, total numeric, notes text, created_at timestamp with time zone, updated_at timestamp with time zone, deleted_at timestamp with time zone, reminders_sent integer, last_reminder_at timestamp with time zone, public_token uuid, signature_data text, signed_at timestamp with time zone, signed_ip character varying, client_email character varying)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id, e.organisation_id, e.client_id, e.estimate_number, e.status,
         e.issue_date, e.valid_until, e.subtotal, e.tax_total, e.total, e.notes,
         e.created_at, e.updated_at, e.deleted_at, e.reminders_sent, e.last_reminder_at,
         e.public_token, e.signature_data, e.signed_at, e.signed_ip, c.email
  FROM estimates e
  JOIN clients c ON e.client_id = c.id AND c.organisation_id = e.organisation_id
  WHERE e.status = 'sent'
    AND e.valid_until < CURRENT_DATE
    AND e.reminders_sent < 3
    AND (e.last_reminder_at IS NULL OR e.last_reminder_at < NOW() - INTERVAL '3 days')
    AND e.deleted_at IS NULL
  FOR UPDATE OF e SKIP LOCKED;
$$;


--
-- Name: list_due_recurring_invoices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_due_recurring_invoices() RETURNS TABLE(id integer, organisation_id integer, client_id integer, template_invoice_id integer, frequency character varying, next_issue_date date, status character varying, notes text, subtotal numeric, tax_total numeric, total numeric, client_email character varying)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT r.id, r.organisation_id, r.client_id, r.template_invoice_id, r.frequency,
         r.next_issue_date, r.status, i.notes, i.subtotal, i.tax_total, i.total, c.email
  FROM recurring_invoices r
  JOIN invoices i ON r.template_invoice_id = i.id
    AND r.organisation_id = i.organisation_id
  JOIN clients c ON r.client_id = c.id
    AND r.organisation_id = c.organisation_id
  WHERE r.status = 'active'
    AND r.next_issue_date <= CURRENT_DATE
    AND r.organisation_id IS NOT NULL
  FOR UPDATE OF r SKIP LOCKED;
$$;


