$$;


--
-- Name: prevent_locked_payroll_input_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_locked_payroll_input_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM payroll_periods p WHERE p.id=COALESCE(NEW.payroll_period_id,OLD.payroll_period_id) AND p.organisation_id=COALESCE(NEW.organisation_id,OLD.organisation_id) AND p.status <> 'open') THEN
    RAISE EXCEPTION 'Une période de paie verrouillée ne peut pas être modifiée';
  END IF;
  RETURN COALESCE(NEW,OLD);
END; $$;


--
-- Name: prevent_posted_accounting_entry_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_posted_accounting_entry_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.status IN ('posted', 'reversed') THEN
    RAISE EXCEPTION 'Une écriture publiée est immuable; créez une écriture de renversement.';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'posted' THEN
    IF NEW.status = 'reversed'
       AND NEW.id = OLD.id
       AND NEW.organisation_id = OLD.organisation_id
       AND NEW.journal_id = OLD.journal_id
       AND NEW.entry_number = OLD.entry_number
       AND NEW.entry_date = OLD.entry_date
       AND NEW.description = OLD.description
       AND NEW.source_type IS NOT DISTINCT FROM OLD.source_type
       AND NEW.source_id IS NOT DISTINCT FROM OLD.source_id
       AND NEW.posted_at IS NOT DISTINCT FROM OLD.posted_at
       AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
       AND NEW.created_at = OLD.created_at THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Une écriture publiée est immuable; créez une écriture de renversement.';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'reversed' THEN
    RAISE EXCEPTION 'Une écriture renversée est immuable.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prevent_posted_accounting_line_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_posted_accounting_line_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_entry_id BIGINT;
DECLARE entry_status VARCHAR(16);
BEGIN
  IF TG_OP = 'INSERT' THEN
    target_entry_id := NEW.entry_id;
  ELSE
    target_entry_id := OLD.entry_id;
  END IF;

  SELECT status INTO entry_status
  FROM accounting_entries
  WHERE id = target_entry_id;

  IF entry_status IN ('posted', 'reversed') THEN
    RAISE EXCEPTION 'Les lignes d’une écriture publiée sont immuables.';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_posted_expense_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_posted_expense_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.accounting_status = 'posted' THEN
    RAISE EXCEPTION 'Une dépense comptabilisée est immuable; utilisez un renversement.';
  END IF;
  RETURN NEW;
END;
$$;


