--
-- Name: purge_activity_logs_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_activity_logs_batch(p_limit integer) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM activity_logs
    WHERE id IN (
      SELECT al.id FROM activity_logs al
      JOIN organisations o ON al.organisation_id = o.id
      WHERE al.captured_at < NOW() - (o.retention_activity_logs_days * INTERVAL '1 day')
        AND al.is_aggregated = true
      LIMIT p_limit
    )
    RETURNING 1
  )
  SELECT COUNT(*)::integer FROM deleted;
$$;


--
-- Name: purge_activity_project_cache_batch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_activity_project_cache_batch() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM activity_project_cache
    WHERE last_used_at < NOW() - INTERVAL '60 days'
       OR (confidence < 30 AND is_manual = FALSE AND last_used_at < NOW() - INTERVAL '7 days')
    RETURNING 1
  )
  SELECT COUNT(*)::integer FROM deleted;
$$;


--
-- Name: purge_activity_summary_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_activity_summary_batch(p_limit integer) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM activity_daily_summary
    WHERE id IN (
      SELECT ads.id FROM activity_daily_summary ads
      JOIN organisations o ON ads.organisation_id = o.id
      WHERE ads.activity_date < CURRENT_DATE - (o.retention_summary_days * INTERVAL '1 day')
      LIMIT p_limit
    )
    RETURNING 1
  )
  SELECT COUNT(*)::integer FROM deleted;
$$;


--
-- Name: purge_security_incidents_buffer_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_security_incidents_buffer_batch(p_limit integer) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM security_incidents_buffer
    WHERE id IN (
      SELECT id FROM security_incidents_buffer
      WHERE (notified_at < NOW() - INTERVAL '30 days')
         OR (created_at < NOW() - INTERVAL '90 days')
      LIMIT p_limit
    )
    RETURNING 1
  )
  SELECT COUNT(*)::integer FROM deleted;
$$;


--
-- Name: purge_soft_deleted_batch(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_soft_deleted_batch(p_table_name text, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_count INTEGER;
BEGIN
  EXECUTE format(
    'DELETE FROM %I WHERE id IN (SELECT id FROM %I WHERE deleted_at < NOW() - INTERVAL ''90 days'' LIMIT $1)',
    p_table_name, p_table_name
  ) USING p_limit;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$_$;


--
-- Name: purge_user_sessions_batch(integer); Type: FUNCTION; Schema: public; Owner: -
