--
-- Name: reconcile_data_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_data_drift() RETURNS TABLE(invoice_id integer, organisation_id integer, status character varying)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT i.id AS invoice_id, i.organisation_id, i.status
  FROM invoices i
  WHERE i.status = 'paid'
    AND NOT EXISTS (
      SELECT 1
      FROM payment_events pe
      JOIN ledger_entries le
        ON le.reference_id = pe.stripe_event_id
       AND le.reference_type = 'stripe_webhook'
       AND le.type = 'payment_received'
      WHERE pe.invoice_id = i.id
        AND pe.type IN (
          'payment_intent.succeeded',
          'charge.succeeded',
          'invoice.payment_succeeded'
        )
    );
$$;


--
-- Name: reconcile_first_invoice_truth(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_first_invoice_truth() RETURNS TABLE(analytics_count bigint, db_count bigint, analytics_without_db bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH analytics_first AS (
    SELECT DISTINCT organisation_id
    FROM analytics_events
    WHERE event_name = 'first_invoice_created'
      AND created_at >= NOW() - INTERVAL '90 days'
  ),
  actual_invoices AS (
    SELECT DISTINCT organisation_id FROM invoices
  )
  SELECT
    (SELECT COUNT(*) FROM analytics_first) AS analytics_count,
    (SELECT COUNT(*) FROM actual_invoices) AS db_count,
    (SELECT COUNT(*) FROM analytics_first a
      LEFT JOIN actual_invoices d ON a.organisation_id = d.organisation_id
      WHERE d.organisation_id IS NULL) AS analytics_without_db;
$$;


--
-- Name: reconcile_ledger_imbalance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_ledger_imbalance() RETURNS TABLE(invoice_id integer, organisation_id integer, invoice_total numeric, ledger_total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH paid_ledger AS (
    SELECT
      pe.invoice_id,
      COALESCE(SUM(le.amount), 0) AS ledger_total
    FROM payment_events pe
    JOIN ledger_entries le
      ON le.reference_id = pe.stripe_event_id
     AND le.reference_type = 'stripe_webhook'
     AND le.type = 'payment_received'
    WHERE pe.type IN (
      'payment_intent.succeeded',
      'charge.succeeded',
      'invoice.payment_succeeded'
    )
    GROUP BY pe.invoice_id
  )
  SELECT
    i.id AS invoice_id,
    i.organisation_id,
    i.total AS invoice_total,
    pl.ledger_total
  FROM invoices i
  JOIN paid_ledger pl ON pl.invoice_id = i.id
  WHERE i.status = 'paid'
    AND ROUND(i.total::numeric, 2) != ROUND(pl.ledger_total::numeric, 2);
$$;


--
-- Name: reconcile_payment_state_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_payment_state_drift() RETURNS TABLE(invoice_id integer, organisation_id integer, status character varying, stripe_event_id character varying)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT
    i.id AS invoice_id,
    i.organisation_id,
    i.status,
    pe.stripe_event_id
  FROM invoices i
  JOIN payment_events pe ON pe.invoice_id = i.id
  JOIN ledger_entries le
    ON le.reference_id = pe.stripe_event_id
   AND le.reference_type = 'stripe_webhook'
   AND le.type = 'payment_received'
  WHERE i.status != 'paid'
    AND pe.type IN (
      'payment_intent.succeeded',
      'charge.succeeded',
      'invoice.payment_succeeded'
    );
$$;


--
-- Name: reconcile_subscription_truth(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_subscription_truth() RETURNS TABLE(analytics_count bigint, db_count bigint, analytics_without_db bigint, db_without_analytics bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH analytics_subs AS (
    SELECT DISTINCT organisation_id
    FROM analytics_events
    WHERE event_name = 'subscription_active'
      AND created_at >= NOW() - INTERVAL '90 days'
  ),
  db_pro AS (
    SELECT id FROM organisations
    WHERE plan_type = 'pro' OR subscription_status = 'active'
  )
  SELECT
    (SELECT COUNT(*) FROM analytics_subs) AS analytics_count,
    (SELECT COUNT(*) FROM db_pro) AS db_count,
    (SELECT COUNT(*) FROM analytics_subs a
      LEFT JOIN db_pro d ON a.organisation_id = d.id
      WHERE d.id IS NULL) AS analytics_without_db,
    (SELECT COUNT(*) FROM db_pro d
      LEFT JOIN analytics_subs a ON d.id = a.organisation_id
      WHERE a.organisation_id IS NULL) AS db_without_analytics;
$$;


--
-- Name: reconcile_webhook_mismatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_webhook_mismatch() RETURNS TABLE(invoice_id integer, stripe_event_id character varying, organisation_id integer, stripe_total numeric, ledger_total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    pe.invoice_id,
    pe.stripe_event_id,
    i.organisation_id,
    CASE
      WHEN pe.type = 'invoice.payment_succeeded'
        THEN (pe.payload->'data'->'object'->>'amount_paid')::numeric / 100
      ELSE (pe.payload->'data'->'object'->>'amount')::numeric / 100
    END AS stripe_total,
    SUM(le.amount) AS ledger_total
  FROM payment_events pe
  JOIN invoices i ON i.id = pe.invoice_id
  JOIN ledger_entries le
    ON le.reference_id = pe.stripe_event_id
   AND le.reference_type = 'stripe_webhook'
   AND le.type = 'payment_received'
  WHERE pe.type IN (
    'payment_intent.succeeded',
    'charge.succeeded',
    'invoice.payment_succeeded'
  )
  GROUP BY pe.invoice_id, pe.stripe_event_id, i.organisation_id, pe.type, pe.payload
  HAVING ROUND((CASE
    WHEN pe.type = 'invoice.payment_succeeded'
      THEN (pe.payload->'data'->'object'->>'amount_paid')::numeric / 100
    ELSE (pe.payload->'data'->'object'->>'amount')::numeric / 100
  END), 2) != ROUND(SUM(le.amount)::numeric, 2);
$$;


--
-- Name: resolve_estimate_public_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_estimate_public_link(p_token_hash text) RETURNS TABLE(link_id bigint, organisation_id integer, estimate_id integer, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE estimate_public_links
     SET last_accessed_at = NOW()
   WHERE token_hash = p_token_hash
     AND revoked_at IS NULL
     AND estimate_public_links.expires_at > NOW()
  RETURNING id, estimate_public_links.organisation_id, estimate_public_links.estimate_id, estimate_public_links.expires_at;
END;
$$;


