END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: retry_metrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retry_metrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    date date NOT NULL,
    hour integer,
    total_attempts integer DEFAULT 0,
    successful integer DEFAULT 0,
    failed_transient integer DEFAULT 0,
    failed_permanent integer DEFAULT 0,
    quarantined integer DEFAULT 0,
    exponential_count integer DEFAULT 0,
    linear_count integer DEFAULT 0,
    fixed_count integer DEFAULT 0,
    avg_backoff_seconds numeric,
    min_backoff_seconds integer,
    max_backoff_seconds integer,
    error_breakdown jsonb,
    top_error character varying(100),
    top_error_count integer,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE retry_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.retry_metrics IS 'Time-series metrics for retry operations and backoff behavior';


--
-- Name: daily_summary; Type: VIEW; Schema: metrics; Owner: -
--

CREATE VIEW metrics.daily_summary AS
 SELECT date,
    (sum(total_attempts))::integer AS retry_total,
    (sum(successful))::integer AS retry_successful,
    (sum(quarantined))::integer AS quarantined_items,
    avg(avg_backoff_seconds) AS avg_backoff_seconds
   FROM public.retry_metrics
  GROUP BY date
  ORDER BY date DESC;


--
-- Name: error_trends; Type: VIEW; Schema: metrics; Owner: -
--

CREATE VIEW metrics.error_trends AS
 SELECT date,
    hour,
    top_error AS error_type,
    top_error_count AS count,
    (round(((100.0 * (top_error_count)::numeric) / (NULLIF(total_attempts, 0))::numeric)))::integer AS percent_of_attempts
   FROM public.retry_metrics
  WHERE ((top_error IS NOT NULL) AND (date >= (CURRENT_DATE - '7 days'::interval)))
  ORDER BY date DESC, hour DESC, top_error_count DESC;


--
-- Name: event_delivery_metrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.event_delivery_metrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    date date NOT NULL,
    hour integer,
    event_handler_name character varying(100) NOT NULL,
    total_events integer DEFAULT 0,
    successful integer DEFAULT 0,
    failed integer DEFAULT 0,
    quarantined integer DEFAULT 0,
    retried integer DEFAULT 0,
    avg_latency_ms numeric,
    min_latency_ms integer,
    max_latency_ms integer,
    p50_latency_ms integer,
    p95_latency_ms integer,
    p99_latency_ms integer,
    success_rate_percent numeric,
    retry_rate_percent numeric,
    error_breakdown jsonb,
    top_error character varying(100),
    top_error_count integer,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE event_delivery_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.event_delivery_metrics IS 'Time-series metrics for event delivery performance by handler';


--
-- Name: job_execution_metrics; Type: TABLE; Schema: public; Owner: -
