-- Name: quarantine_metrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.quarantine_metrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    date date NOT NULL,
    hour integer,
    total_items integer DEFAULT 0,
    waiting_recovery integer DEFAULT 0,
    in_recovery integer DEFAULT 0,
    recovered integer DEFAULT 0,
    permanently_failed integer DEFAULT 0,
    items_0_1h integer DEFAULT 0,
    items_1_24h integer DEFAULT 0,
    items_1_7d integer DEFAULT 0,
    items_7d_plus integer DEFAULT 0,
    recovery_attempts integer DEFAULT 0,
    recovery_successes integer DEFAULT 0,
    recovery_failures integer DEFAULT 0,
    avg_recovery_attempts numeric,
    work_type_breakdown jsonb,
    top_work_type character varying(100),
    top_work_type_count integer,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE quarantine_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.quarantine_metrics IS 'Time-series metrics for quarantine queue and recovery operations';


--
-- Name: hourly_summary; Type: VIEW; Schema: metrics; Owner: -
--

CREATE VIEW metrics.hourly_summary AS
 SELECT COALESCE(rm.date, qm.date, edm.date, jem.date) AS date,
    COALESCE(rm.hour, qm.hour, edm.hour, jem.hour) AS hour,
    max(rm.total_attempts) AS retry_total,
    max(rm.successful) AS retry_successful,
    max(rm.failed_transient) AS retry_transient,
    max(rm.failed_permanent) AS retry_permanent,
    max(qm.total_items) AS quarantine_items,
    max(qm.recovered) AS quarantine_recovered,
    max(qm.recovery_attempts) AS recovery_attempts,
    (sum(edm.total_events))::integer AS delivery_total,
    (sum(edm.successful))::integer AS delivery_successful,
    avg(edm.avg_latency_ms) AS avg_delivery_latency_ms,
    (sum(jem.total_executions))::integer AS job_executions,
    (sum(jem.successful))::integer AS job_successes,
    (sum(jem.sla_breaches))::integer AS sla_breaches
   FROM (((public.retry_metrics rm
     FULL JOIN public.quarantine_metrics qm USING (date, hour))
     FULL JOIN public.event_delivery_metrics edm USING (date, hour))
     FULL JOIN public.job_execution_metrics jem USING (date, hour))
  WHERE (COALESCE(rm.date, qm.date, edm.date, jem.date) >= (CURRENT_DATE - '1 day'::interval))
  GROUP BY COALESCE(rm.date, qm.date, edm.date, jem.date), COALESCE(rm.hour, qm.hour, edm.hour, jem.hour);


--
-- Name: sla_compliance; Type: VIEW; Schema: metrics; Owner: -
--

CREATE VIEW metrics.sla_compliance AS
 SELECT date,
    job_name,
    total_executions,
    successful,
    timed_out,
    (round(((100.0 * (successful)::numeric) / (NULLIF(total_executions, 0))::numeric)))::integer AS success_rate_percent,
    sla_met,
    sla_breaches
   FROM public.job_execution_metrics
  WHERE (date >= (CURRENT_DATE - '30 days'::interval))
  ORDER BY date DESC, job_name;


