--
-- Name: backup_status_summary; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.backup_status_summary AS
 SELECT bs.id AS snapshot_id,
    bs.backup_type,
    bs.status,
    bs.total_size_bytes,
    bs.components_backed_up,
    bs.verified,
    bs.verified_at AS last_verification_at,
    bs.created_at,
    (EXTRACT(epoch FROM (bs.end_time - bs.start_time)))::integer AS duration_seconds,
    count(DISTINCT bc.component_name) AS components_in_snapshot,
    sum(
        CASE
            WHEN ((bv.status)::text = 'passed'::text) THEN 1
            ELSE 0
        END) AS verifications_passed,
    sum(
        CASE
            WHEN ((bv.status)::text = 'failed'::text) THEN 1
            ELSE 0
        END) AS verifications_failed
   FROM ((public.backup_snapshots bs
     LEFT JOIN public.backup_components bc ON ((bc.snapshot_id = bs.id)))
     LEFT JOIN public.backup_verifications bv ON ((bv.snapshot_id = bs.id)))
  WHERE (bs.created_at >= (CURRENT_TIMESTAMP - '30 days'::interval))
  GROUP BY bs.id, bs.backup_type, bs.status, bs.total_size_bytes, bs.components_backed_up, bs.verified, bs.verified_at, bs.created_at, bs.end_time, bs.start_time;


--
-- Name: backup_timeline; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.backup_timeline AS
 SELECT date(created_at) AS backup_date,
    backup_type,
    count(*) AS snapshot_count,
    sum(total_size_bytes) AS total_size_bytes,
    count(*) FILTER (WHERE ((status)::text = 'completed'::text)) AS successful_backups,
    count(*) FILTER (WHERE ((status)::text = 'failed'::text)) AS failed_backups,
    (avg(EXTRACT(epoch FROM (end_time - start_time))))::integer AS avg_duration_seconds,
    count(*) FILTER (WHERE (verified = true)) AS verified_count
   FROM public.backup_snapshots bs
  WHERE (created_at >= (CURRENT_TIMESTAMP - '90 days'::interval))
  GROUP BY (date(created_at)), backup_type
  ORDER BY (date(created_at)) DESC;


--
-- Name: backup_verification_summary; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.backup_verification_summary AS
 SELECT bs.id AS snapshot_id,
    bs.backup_type,
    bs.created_at,
    count(*) AS total_verifications,
    count(*) FILTER (WHERE ((bv.status)::text = 'passed'::text)) AS passed_verifications,
    count(*) FILTER (WHERE ((bv.status)::text = 'failed'::text)) AS failed_verifications,
    count(*) FILTER (WHERE ((bv.status)::text = 'warning'::text)) AS warning_verifications,
    max(bv.verified_at) AS last_verification_at
   FROM (public.backup_snapshots bs
     LEFT JOIN public.backup_verifications bv ON ((bv.snapshot_id = bs.id)))
  WHERE (bs.created_at >= (CURRENT_TIMESTAMP - '30 days'::interval))
  GROUP BY bs.id, bs.backup_type, bs.created_at
  ORDER BY bs.created_at DESC;


