    duration_ms numeric NOT NULL,
    status text NOT NULL,
    error_message text,
    tags jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT traces_duration_ms_check CHECK ((duration_ms >= (0)::numeric)),
    CONSTRAINT traces_status_check CHECK ((status = ANY (ARRAY['success'::text, 'error'::text, 'timeout'::text])))
);


