COMMENT ON COLUMN observability.traces.tags IS 'Context: {service, endpoint, http_method, status_code, user_id, resource_id}';


--
-- Name: error_rates; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.error_rates AS
 SELECT service_name,
    date_trunc('minute'::text, start_time) AS minute,
    count(*) AS total_requests,
    count(*) FILTER (WHERE (status = 'error'::text)) AS error_count,
    round(((100.0 * (count(*) FILTER (WHERE (status = 'error'::text)))::numeric) / (count(*))::numeric), 2) AS error_rate_pct
   FROM observability.traces
  WHERE (start_time > (now() - '24:00:00'::interval))
  GROUP BY service_name, (date_trunc('minute'::text, start_time));


--
-- Name: VIEW error_rates; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON VIEW observability.error_rates IS 'Error rate % per service per minute, last 24 hours.';


