--
-- Name: evidence_chain_verification; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.evidence_chain_verification AS
 SELECT ee.id,
    ee.event_timestamp,
    ec.chain_valid,
    ec.chain_verified_at,
        CASE
            WHEN (ec.chain_valid = false) THEN 'TAMPERED'::text
            WHEN (es.verified = false) THEN 'UNVERIFIED'::text
            WHEN (ee.on_hold = true) THEN 'ON_HOLD'::text
            ELSE 'VALID'::text
        END AS verification_status,
    count(
        CASE
            WHEN (eal.access_granted = true) THEN 1
            ELSE NULL::integer
        END) AS access_count
   FROM (((public.evidence_entries ee
     LEFT JOIN public.evidence_chains ec ON ((ec.entry_id = ee.id)))
     LEFT JOIN public.evidence_signatures es ON ((es.entry_id = ee.id)))
     LEFT JOIN public.evidence_access_log eal ON ((eal.accessed_entry_id = ee.id)))
  GROUP BY ee.id, ee.event_timestamp, ec.chain_valid, ec.chain_verified_at, es.verified, ee.on_hold;


--
-- Name: evidence_archival; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.evidence_archival (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    archive_date date NOT NULL,
    entry_count integer NOT NULL,
    total_size_bytes bigint,
    archive_location character varying(500) NOT NULL,
    retention_category character varying(100),
    expiry_date date,
    checksum character varying(64),
    entries_archived jsonb,
    archived_by character varying(255) NOT NULL,
    archived_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE evidence_archival; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.evidence_archival IS 'Tracking of archived evidence in cold storage';


--
-- Name: evidence_retention_status; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.evidence_retention_status AS
 SELECT COALESCE(ea.retention_category, 'active'::character varying) AS retention_category,
    count(ee.id) AS entry_count,
    sum(
        CASE
            WHEN (ee.archived = true) THEN 1
            ELSE 0
        END) AS archived_count,
    sum(
        CASE
            WHEN (ee.on_hold = true) THEN 1
            ELSE 0
        END) AS on_hold_count,
    max(ee.event_timestamp) AS latest_entry,
    COALESCE((ea.expiry_date)::text, 'indefinite'::text) AS retention_until
   FROM (public.evidence_entries ee
     LEFT JOIN public.evidence_archival ea ON ((ea.id = ( SELECT evidence_archival.id
           FROM public.evidence_archival
          WHERE (ee.id IN ( SELECT (jsonb_array_elements_text.value)::uuid AS value
                   FROM jsonb_array_elements_text(COALESCE(ea.entries_archived, '[]'::jsonb)) jsonb_array_elements_text(value)))
          ORDER BY evidence_archival.archive_date DESC
         LIMIT 1))))
  GROUP BY COALESCE(ea.retention_category, 'active'::character varying), ea.expiry_date;


--
-- Name: evidence_timeline; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.evidence_timeline AS
 SELECT ee.id,
    ee.entry_type,
    ee.component_name,
    ee.resource_type,
    ee.resource_id,
    ee.action,
    ee.status,
    ee.initiator_user_id,
    ee.event_timestamp,
    ec.chain_valid,
    es.verified AS signature_verified,
    ee.on_hold,
    ee.archived
   FROM ((public.evidence_entries ee
     LEFT JOIN public.evidence_chains ec ON ((ec.entry_id = ee.id)))
     LEFT JOIN public.evidence_signatures es ON ((es.entry_id = ee.id)))
  ORDER BY ee.event_timestamp DESC;


--
-- Name: health_check_results; Type: TABLE; Schema: observability; Owner: -
--

CREATE TABLE observability.health_check_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    service_name text NOT NULL,
    probe_name text NOT NULL,
    status text NOT NULL,
    latency_ms integer,
    error_message text,
    checked_at timestamp with time zone NOT NULL,
    next_check_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    component_name character varying(100),
    alert_severity character varying(50),
    metadata jsonb,
    remediation_steps text,
    CONSTRAINT health_check_results_latency_ms_check CHECK ((latency_ms >= 0)),
    CONSTRAINT health_check_results_status_check CHECK ((status = ANY (ARRAY['healthy'::text, 'degraded'::text, 'unhealthy'::text])))
);


--
-- Name: TABLE health_check_results; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON TABLE observability.health_check_results IS 'Health check probe results. Immutable record of service readiness and liveness checks.';


--
-- Name: COLUMN health_check_results.probe_name; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON COLUMN observability.health_check_results.probe_name IS 'Probe type: database, redis, queue, api, external_api, disk, memory';


--
-- Name: COLUMN health_check_results.status; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON COLUMN observability.health_check_results.status IS 'healthy (all thresholds ok), degraded (some thresholds exceeded), unhealthy (service down)';


--
-- Name: COLUMN health_check_results.latency_ms; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON COLUMN observability.health_check_results.latency_ms IS 'Response time in milliseconds';


--
-- Name: COLUMN health_check_results.next_check_at; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON COLUMN observability.health_check_results.next_check_at IS 'When next check is scheduled';


--
-- Name: health_summary; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.health_summary AS
 SELECT service_name,
    (array_agg(status ORDER BY checked_at DESC))[1] AS overall_status,
    (array_agg(latency_ms ORDER BY checked_at DESC))[1] AS latest_latency_ms,
    (array_agg(checked_at ORDER BY checked_at DESC))[1] AS last_checked_at,
    count(*) FILTER (WHERE (status = 'healthy'::text)) AS healthy_probes,
    count(*) FILTER (WHERE (status = 'degraded'::text)) AS degraded_probes,
    count(*) FILTER (WHERE (status = 'unhealthy'::text)) AS unhealthy_probes,
    max(latency_ms) AS max_latency_ms,
    avg(latency_ms) AS avg_latency_ms
   FROM observability.health_check_results
  WHERE (checked_at > (now() - '01:00:00'::interval))
  GROUP BY service_name;


--
-- Name: VIEW health_summary; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON VIEW observability.health_summary IS 'Latest health status per service, last hour only';


--
-- Name: incident_rca; Type: TABLE; Schema: observability; Owner: -
--

