    start_time timestamp with time zone NOT NULL,
    detection_time timestamp with time zone,
    resolution_time timestamp with time zone,
    severity text,
    root_cause text,
    contributing_factors text[],
    impact_summary text,
    lessons_learned text[],
    actions jsonb,
    timeline jsonb,
    facilitator_id uuid,
    participants text[],
    status text DEFAULT 'open'::text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT incident_rca_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT incident_rca_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_review'::text, 'closed'::text, 'archived'::text])))
);


--
-- Name: TABLE incident_rca; Type: COMMENT; Schema: observability; Owner: -
