COMMENT ON COLUMN observability.incident_rca.actions IS 'Follow-up actions to prevent recurrence: owner, due date, status';


--
-- Name: COLUMN incident_rca.timeline; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON COLUMN observability.incident_rca.timeline IS 'Immutable timeline: when what happened and who was involved';


--
-- Name: latency_percentiles; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.latency_percentiles AS
 SELECT service_name,
    date_trunc('minute'::text, start_time) AS minute,
    count(*) AS request_count,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS p50_ms,
    percentile_cont((0.95)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS p95_ms,
    percentile_cont((0.99)::double precision) WITHIN GROUP (ORDER BY ((duration_ms)::double precision)) AS p99_ms,
    max(duration_ms) AS max_ms,
    (avg(duration_ms))::numeric(10,2) AS avg_ms
   FROM observability.traces
  WHERE (start_time > (now() - '24:00:00'::interval))
  GROUP BY service_name, (date_trunc('minute'::text, start_time));


--
-- Name: VIEW latency_percentiles; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON VIEW observability.latency_percentiles IS 'p50/p95/p99 latency per service per minute, last 24 hours.';


