-- Name: restore_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.restore_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_snapshot_id uuid NOT NULL,
    target_environment character varying(50) NOT NULL,
    status character varying(50) NOT NULL,
    start_time timestamp with time zone NOT NULL,
    end_time timestamp with time zone,
    duration_ms integer,
    restore_scope character varying(100),
    components_restored integer,
    tables_restored integer,
    total_rows_restored bigint,
    verified_after_restore boolean DEFAULT false,
    verification_status character varying(50),
    errors jsonb,
    error_count integer DEFAULT 0,
    initiated_by character varying(255) NOT NULL,
    initiator_reason text,
    pre_restore_snapshot_id uuid,
    rollback_performed boolean DEFAULT false,
    rollback_time timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE restore_operations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.restore_operations IS 'Log of all restore operations with outcome and error tracking';


--
-- Name: recent_restore_operations; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.recent_restore_operations AS
 SELECT id,
    source_snapshot_id,
    target_environment,
    status,
    total_rows_restored,
    verified_after_restore,
    initiated_by,
    created_at,
    (EXTRACT(epoch FROM (end_time - start_time)))::integer AS duration_seconds,
    COALESCE(error_count, 0) AS error_count
   FROM public.restore_operations ro
  WHERE (created_at >= (CURRENT_TIMESTAMP - '7 days'::interval))
  ORDER BY created_at DESC;


