    error_budget_used_minutes numeric NOT NULL,
    error_budget_remaining_minutes numeric NOT NULL,
    error_budget_used_pct numeric NOT NULL,
    burn_rate_pct_per_hour numeric,
    alert_fired boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sla_burn_rate_actual_uptime_pct_check CHECK (((actual_uptime_pct >= (0)::numeric) AND (actual_uptime_pct <= (100)::numeric))),
    CONSTRAINT sla_burn_rate_sla_target_pct_check CHECK (((sla_target_pct >= (0)::numeric) AND (sla_target_pct <= (100)::numeric)))
);


