--

COMMENT ON TABLE observability.sla_burn_rate IS 'SLA tracking per service. Computed from traces. Error budget burn rate triggers alerts.';


--
-- Name: stage5_health_summary; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.stage5_health_summary AS
 SELECT component_name,
    count(*) FILTER (WHERE (status = 'healthy'::text)) AS healthy_probes,
    count(*) FILTER (WHERE (status = 'degraded'::text)) AS degraded_probes,
    count(*) FILTER (WHERE (status = 'unhealthy'::text)) AS unhealthy_probes,
    count(*) FILTER (WHERE ((alert_severity)::text = 'warning'::text)) AS warning_alerts,
    count(*) FILTER (WHERE ((alert_severity)::text = 'critical'::text)) AS critical_alerts,
    max(
        CASE
            WHEN (status = 'unhealthy'::text) THEN 'unhealthy'::text
            WHEN (status = 'degraded'::text) THEN 'degraded'::text
            ELSE 'healthy'::text
        END) AS overall_status,
    max(checked_at) AS last_checked_at,
    avg(latency_ms) AS avg_latency_ms
   FROM observability.health_check_results
  WHERE (checked_at > (CURRENT_TIMESTAMP - '01:00:00'::interval))
  GROUP BY component_name;


--
-- Name: VIEW stage5_health_summary; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON VIEW observability.stage5_health_summary IS 'Current health status by component';


--
-- Name: throughput_metrics; Type: VIEW; Schema: observability; Owner: -
--

CREATE VIEW observability.throughput_metrics AS
 SELECT service_name,
    date_trunc('minute'::text, start_time) AS minute,
    count(*) AS requests_per_minute,
    (((count(*) FILTER (WHERE (status = 'success'::text)))::numeric / (count(*))::numeric) * (100)::numeric) AS success_rate_pct
   FROM observability.traces
  WHERE (start_time > (now() - '24:00:00'::interval))
  GROUP BY service_name, (date_trunc('minute'::text, start_time));


--
-- Name: VIEW throughput_metrics; Type: COMMENT; Schema: observability; Owner: -
--

COMMENT ON VIEW observability.throughput_metrics IS 'Requests per minute and success rate per service.';


