--
-- Name: abuse_detection_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.abuse_detection_summary AS
 SELECT organization_id,
    alert_type,
    count(*) AS total_alerts,
    count(
        CASE
            WHEN (is_active = true) THEN 1
            ELSE NULL::integer
        END) AS active_alerts,
    count(
        CASE
            WHEN (is_blocked = true) THEN 1
            ELSE NULL::integer
        END) AS blocked_entities,
    count(
        CASE
            WHEN ((severity_level)::text = 'critical'::text) THEN 1
            ELSE NULL::integer
        END) AS critical_alerts,
    avg(confidence_score) AS avg_confidence,
    max(detected_at) AS most_recent_alert
   FROM public.abuse_detection_alerts
  GROUP BY organization_id, alert_type;


