COMMENT ON TABLE public.auth_sessions IS 'Track active user sessions with device, location, and security information';


--
-- Name: active_sessions_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.active_sessions_summary AS
 SELECT organization_id,
    count(DISTINCT user_id) AS active_users,
    count(*) AS total_sessions,
    count(
        CASE
            WHEN ((is_active = true) AND (is_expired = false) AND (is_revoked = false)) THEN 1
            ELSE NULL::integer
        END) AS valid_sessions,
    count(
        CASE
            WHEN (device_approved_at IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS approved_devices,
    count(DISTINCT device_type) AS device_types
   FROM public.auth_sessions
  WHERE ((is_active = true) AND (is_expired = false))
  GROUP BY organization_id;


