    scope character varying(255),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at timestamp with time zone,
    rotated_at timestamp with time zone,
    next_rotation_at timestamp with time zone,
    rotation_interval_days integer DEFAULT 90,
    last_used_at timestamp with time zone,
    last_used_ip inet,
    usage_count integer DEFAULT 0,
    is_active boolean DEFAULT true,
    is_revoked boolean DEFAULT false,
    revoke_reason text,
    revoked_at timestamp with time zone
);


--
-- Name: TABLE api_keys; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.api_keys IS 'Manage API keys with rotation schedules and usage tracking';


--
-- Name: api_key_status_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.api_key_status_summary AS
 SELECT user_id,
    count(*) AS total_keys,
    count(
        CASE
            WHEN ((is_active = true) AND (is_revoked = false)) THEN 1
            ELSE NULL::integer
        END) AS active_keys,
    count(
        CASE
            WHEN ((expires_at IS NOT NULL) AND (expires_at < CURRENT_TIMESTAMP)) THEN 1
            ELSE NULL::integer
        END) AS expired_keys,
    count(
        CASE
            WHEN (next_rotation_at < CURRENT_TIMESTAMP) THEN 1
            ELSE NULL::integer
        END) AS keys_needing_rotation,
    max(last_used_at) AS most_recent_usage
   FROM public.api_keys
  GROUP BY user_id;


