    artifact_version character varying(100),
    artifact_location character varying(500),
    artifact_size_bytes bigint,
    artifact_hash character varying(255),
    artifact_signature character varying(500),
    signature_algorithm character varying(50),
    signature_verified boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    published_at timestamp with time zone,
    is_published boolean DEFAULT false,
    is_deprecated boolean DEFAULT false,
    deprecation_reason text
);


--
-- Name: TABLE build_artifacts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.build_artifacts IS 'Track build output with integrity verification and cryptographic signatures';


--
-- Name: artifact_integrity_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.artifact_integrity_summary AS
 SELECT artifact_type,
    count(*) AS total_artifacts,
    count(
        CASE
            WHEN (signature_verified = true) THEN 1
            ELSE NULL::integer
        END) AS verified_artifacts,
    count(
        CASE
            WHEN (is_published = true) THEN 1
            ELSE NULL::integer
        END) AS published_artifacts,
    count(
        CASE
            WHEN (is_deprecated = true) THEN 1
            ELSE NULL::integer
        END) AS deprecated_artifacts
   FROM public.build_artifacts
  GROUP BY artifact_type;


