-- Name: TABLE authentication_methods; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.authentication_methods IS 'Track available authentication methods for each user (password, 2FA, SSO, API key)';


--
-- Name: authentication_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.authentication_summary AS
 SELECT event_type,
    count(*) AS total_events,
    count(
        CASE
            WHEN (success = true) THEN 1
            ELSE NULL::integer
        END) AS successful,
    count(
        CASE
            WHEN (success = false) THEN 1
            ELSE NULL::integer
        END) AS failed,
    count(
        CASE
            WHEN (is_suspicious = true) THEN 1
            ELSE NULL::integer
        END) AS suspicious,
    max(event_timestamp) AS most_recent
   FROM public.authentication_events
  WHERE (event_timestamp >= (CURRENT_TIMESTAMP - '7 days'::interval))
  GROUP BY event_type;


