--
-- Name: build_status_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.build_status_summary AS
 SELECT organization_id,
    build_type,
    count(*) AS total_builds,
    count(
        CASE
            WHEN ((status)::text = 'passed'::text) THEN 1
            ELSE NULL::integer
        END) AS passed_builds,
    count(
        CASE
            WHEN ((status)::text = 'failed'::text) THEN 1
            ELSE NULL::integer
        END) AS failed_builds,
    count(
        CASE
            WHEN (security_scan_passed = false) THEN 1
            ELSE NULL::integer
        END) AS security_failures,
    count(
        CASE
            WHEN (dependency_validation_passed = false) THEN 1
            ELSE NULL::integer
        END) AS dependency_failures,
    count(
        CASE
            WHEN (vulnerabilities_found > 0) THEN 1
            ELSE NULL::integer
        END) AS builds_with_vulnerabilities,
    avg(duration_minutes) AS avg_build_duration_minutes,
    max(completed_at) AS most_recent_build
   FROM public.build_configurations
  WHERE (completed_at IS NOT NULL)
  GROUP BY organization_id, build_type;


