--
-- Name: data_protection_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.data_protection_summary AS
 SELECT dc.classification_name,
    dc.classification_level,
    count(DISTINCT dfc.id) AS fields_classified,
    count(DISTINCT
        CASE
            WHEN (dfc.access_log_all_reads = true) THEN dfc.id
            ELSE NULL::uuid
        END) AS fields_with_read_logging,
    count(DISTINCT
        CASE
            WHEN (dfc.access_require_approval = true) THEN dfc.id
            ELSE NULL::uuid
        END) AS fields_requiring_approval,
    count(DISTINCT
        CASE
            WHEN (dfc.pii_type IS NOT NULL) THEN dfc.id
            ELSE NULL::uuid
        END) AS pii_fields
   FROM (public.data_classifications dc
     LEFT JOIN public.data_field_classifications dfc ON ((dfc.data_classification_id = dc.id)))
  WHERE (dc.is_active = true)
  GROUP BY dc.id, dc.classification_name, dc.classification_level;


