--
-- Name: dependency_vulnerability_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dependency_vulnerability_summary AS
 SELECT pd.package_name,
    pd.package_version,
    count(DISTINCT dv.id) AS total_vulnerabilities,
    count(
        CASE
            WHEN ((dv.severity_level)::text = 'critical'::text) THEN 1
            ELSE NULL::integer
        END) AS critical_count,
    count(
        CASE
            WHEN ((dv.severity_level)::text = 'high'::text) THEN 1
            ELSE NULL::integer
        END) AS high_count,
    count(
        CASE
            WHEN ((dv.status)::text = 'open'::text) THEN 1
            ELSE NULL::integer
        END) AS open_vulnerabilities,
    max(dv.cvss_score) AS max_cvss_score,
    max(dv.discovered_at) AS most_recent_vulnerability
   FROM (public.package_dependencies pd
     LEFT JOIN public.dependency_vulnerabilities dv ON ((dv.package_dependency_id = pd.id)))
  GROUP BY pd.package_name, pd.package_version;


