-- Name: encryption_keys; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.encryption_keys (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key_name character varying(255) NOT NULL,
    key_id character varying(255) NOT NULL,
    key_algorithm character varying(50),
    key_type character varying(50),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    rotated_at timestamp with time zone,
    next_rotation_at timestamp with time zone,
    rotation_interval_days integer,
    is_active boolean DEFAULT true,
    is_retired boolean DEFAULT false,
    uses_external_kms boolean DEFAULT true,
    organization_id character varying(255),
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE encryption_keys; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.encryption_keys IS 'Manage encryption keys with rotation schedules and KMS integration';


--
-- Name: encryption_key_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.encryption_key_status AS
 SELECT key_name,
    key_algorithm,
    is_active,
    is_retired,
    EXTRACT(day FROM (next_rotation_at - CURRENT_TIMESTAMP)) AS days_until_rotation,
        CASE
            WHEN (next_rotation_at < CURRENT_TIMESTAMP) THEN 'OVERDUE'::text
            WHEN (next_rotation_at < (CURRENT_TIMESTAMP + '30 days'::interval)) THEN 'DUE_SOON'::text
            ELSE 'OK'::text
        END AS rotation_status
   FROM public.encryption_keys
  ORDER BY next_rotation_at;


