    CONSTRAINT help_chat_messages_role_check CHECK (((role)::text = ANY ((ARRAY['user'::character varying, 'assistant'::character varying])::text[])))
);


--
-- Name: TABLE help_chat_messages; Type: COMMENT; Schema: public; Owner: -
--

