    id integer NOT NULL,
    organisation_id integer NOT NULL,
    user_id integer,
    session_id character varying(100) NOT NULL,
    language character varying(10) DEFAULT 'fr'::character varying NOT NULL,
    title character varying(255),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    last_activity_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);


--
-- Name: TABLE help_chat_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.help_chat_sessions IS 'Stores AI chatbot conversation sessions';


--
-- Name: COLUMN help_chat_sessions.session_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.help_chat_sessions.session_id IS 'Unique session identifier (UUID)';


--
-- Name: COLUMN help_chat_sessions.language; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.help_chat_sessions.language IS 'Language of the conversation (fr, en, es, de, pt, it)';


--
-- Name: help_chat_active_sessions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.help_chat_active_sessions AS
 SELECT hcs.id,
    hcs.organisation_id,
    hcs.user_id,
    hcs.session_id,
    hcs.language,
    hcs.title,
    hcs.created_at,
    hcs.last_activity_at,
    count(hcm.id) AS message_count,
    max(hcm.created_at) AS last_message_at
   FROM (public.help_chat_sessions hcs
     LEFT JOIN public.help_chat_messages hcm ON (((hcs.session_id)::text = (hcm.session_id)::text)))
  WHERE (hcs.organisation_id = (current_setting('app.current_organisation_id'::text))::integer)
  GROUP BY hcs.id, hcs.organisation_id, hcs.user_id, hcs.session_id, hcs.language, hcs.title, hcs.created_at, hcs.last_activity_at;


