--
-- Name: help_chat_statistics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.help_chat_statistics AS
 SELECT organisation_id,
    count(DISTINCT session_id) AS total_sessions,
    count(DISTINCT user_id) AS unique_users,
    count(*) AS total_messages,
    avg(tokens_used) AS avg_tokens_per_message,
    max(created_at) AS last_message_at
   FROM public.help_chat_messages
  WHERE (organisation_id = (current_setting('app.current_organisation_id'::text))::integer)
  GROUP BY organisation_id;


