--
-- Name: pending_approvals_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pending_approvals_summary AS
 SELECT count(*) AS pending_count,
    count(
        CASE
            WHEN (expires_at < CURRENT_TIMESTAMP) THEN 1
            ELSE NULL::integer
        END) AS expired_count,
    count(
        CASE
            WHEN (self_approval_detected = true) THEN 1
            ELSE NULL::integer
        END) AS self_approval_risks,
    count(
        CASE
            WHEN (authority_elevation_detected = true) THEN 1
            ELSE NULL::integer
        END) AS elevation_risks,
    count(
        CASE
            WHEN (field_bypass_detected = true) THEN 1
            ELSE NULL::integer
        END) AS field_bypass_risks
   FROM public.operation_approvals
  WHERE ((status)::text = 'pending'::text);


