--
-- Name: pii_exposure_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pii_exposure_summary AS
 SELECT pii_types.pii_type,
    count(DISTINCT data_access_log.table_name) AS tables_with_pii,
    count(DISTINCT data_access_log.record_id) AS records_with_pii,
    count(
        CASE
            WHEN (data_access_log.access_timestamp >= (CURRENT_TIMESTAMP - '24:00:00'::interval)) THEN 1
            ELSE NULL::integer
        END) AS accesses_last_24h,
    count(DISTINCT data_access_log.user_id) AS users_accessed_pii
   FROM (public.data_access_log
     CROSS JOIN LATERAL jsonb_array_elements_text(data_access_log.affected_pii_types) pii_types(pii_type))
  WHERE ((data_access_log.affected_pii_types IS NOT NULL) AND (jsonb_typeof(data_access_log.affected_pii_types) = 'array'::text))
  GROUP BY pii_types.pii_type;


