    permanent_error_code character varying(50),
    permanent_error_message text,
    total_attempts integer NOT NULL,
    first_attempt_at timestamp with time zone NOT NULL,
    last_attempt_at timestamp with time zone NOT NULL,
    payload jsonb NOT NULL,
    tags character varying(255)[] DEFAULT '{}'::character varying[],
    recovery_attempts integer DEFAULT 0,
    last_recovery_attempt_at timestamp with time zone,
    recovery_status character varying(50),
    notes text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT quarantine_work_type_id_not_empty CHECK ((((work_type)::text <> ''::text) AND ((work_id)::text <> ''::text))),
    CONSTRAINT valid_reason CHECK (((reason)::text = ANY (ARRAY[('max_retries_exceeded'::character varying)::text, ('permanent_error'::character varying)::text, ('manual_quarantine'::character varying)::text])))
);


