    applies_to character varying(100),
    endpoint_pattern character varying(255),
    http_methods jsonb,
    exempt_users jsonb,
    return_429_on_limit boolean DEFAULT true,
    return_retry_after boolean DEFAULT true,
    queue_requests boolean DEFAULT false,
    is_active boolean DEFAULT true,
