--
-- Name: rate_limit_tracking; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.rate_limit_tracking (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rate_limit_policy_id uuid NOT NULL,
    user_id character varying(255),
    api_key_id character varying(255),
    ip_address inet,
    organization_id character varying(255) NOT NULL,
    requests_in_window integer DEFAULT 0,
    requests_this_second integer DEFAULT 0,
    requests_this_minute integer DEFAULT 0,
    requests_this_hour integer DEFAULT 0,
    requests_this_day integer DEFAULT 0,
    window_reset_at timestamp with time zone,
    last_request_at timestamp with time zone,
    burst_requests_used integer DEFAULT 0,
    limit_exceeded_count integer DEFAULT 0,
    last_limit_exceeded_at timestamp with time zone,
    is_currently_limited boolean DEFAULT false,
    limited_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE rate_limit_tracking; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rate_limit_tracking IS 'Track rate limit usage per user/API key/IP';


--
-- Name: rate_limit_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.rate_limit_summary AS
 SELECT organization_id,
    count(DISTINCT rate_limit_policy_id) AS total_policies,
    count(
        CASE
            WHEN (is_currently_limited = true) THEN 1
            ELSE NULL::integer
        END) AS currently_limited_entities,
    count(DISTINCT user_id) AS tracked_users,
    count(DISTINCT ip_address) AS tracked_ips,
    max(last_limit_exceeded_at) AS most_recent_limit_exceeded
   FROM public.rate_limit_tracking
  GROUP BY organization_id;


