--
-- Name: recent_authorization_decisions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.recent_authorization_decisions AS
 SELECT user_id,
    organization_id,
    action_type,
    route_path,
    http_method,
    decision,
    denial_reason,
    created_at,
    count(*) OVER (PARTITION BY user_id, decision ORDER BY created_at DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS decision_sequence
   FROM public.authorization_audit aa
  WHERE (created_at >= (CURRENT_TIMESTAMP - '24:00:00'::interval))
  ORDER BY created_at DESC;


--
-- Name: recent_data_access_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.recent_data_access_summary AS
 SELECT table_name,
    access_type,
    count(*) AS access_count,
    count(DISTINCT user_id) AS unique_users,
    count(
        CASE
            WHEN (flagged_for_review = true) THEN 1
            ELSE NULL::integer
        END) AS flagged_accesses,
    max(access_timestamp) AS most_recent_access
   FROM public.data_access_log
  WHERE (access_timestamp >= (CURRENT_TIMESTAMP - '7 days'::interval))
  GROUP BY table_name, access_type;


