--
-- Name: replay_attack_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.replay_attack_summary AS
 SELECT operation_type,
    user_id,
    count(*) AS total_attempts,
    count(
        CASE
            WHEN (replay_attempt_count > 0) THEN 1
            ELSE NULL::integer
        END) AS with_replays,
    max(last_replay_attempt_at) AS most_recent_replay
   FROM public.operation_idempotency_keys
  WHERE (last_replay_attempt_at IS NOT NULL)
  GROUP BY operation_type, user_id;


