CREATE TABLE public.retry_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_type character varying(100) NOT NULL,
    work_id character varying(255) NOT NULL,
    attempt_number integer NOT NULL,
    attempt_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    duration_ms integer,
    status character varying(50) NOT NULL,
    error_classification character varying(50),
    error_message text,
    error_code character varying(50),
    backoff_strategy character varying(50) DEFAULT 'exponential'::character varying NOT NULL,
    backoff_multiplier numeric(5,2) DEFAULT 1.5,
    backoff_seconds integer,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT valid_backoff CHECK (((backoff_strategy)::text = ANY (ARRAY[('exponential'::character varying)::text, ('linear'::character varying)::text, ('fixed'::character varying)::text]))),
    CONSTRAINT valid_classification CHECK (((error_classification)::text = ANY (ARRAY[('network'::character varying)::text, ('validation'::character varying)::text, ('internal'::character varying)::text, ('rate_limit'::character varying)::text, ('timeout'::character varying)::text, ('permanent'::character varying)::text, ('unknown'::character varying)::text]))),
    CONSTRAINT valid_status CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('in_progress'::character varying)::text, ('success'::character varying)::text, ('failed_transient'::character varying)::text, ('failed_permanent'::character varying)::text])))
);


