    max_total_duration_seconds integer,
    retryable_error_codes character varying(50)[] DEFAULT '{}'::character varying[],
    permanent_error_codes character varying(50)[] DEFAULT '{}'::character varying[],
    quarantine_on_permanent_error boolean DEFAULT true,
    auto_quarantine_after_attempts integer,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


