--
-- Name: route_coverage_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.route_coverage_status AS
 SELECT http_method,
    route_path,
    route_name,
        CASE
            WHEN (required_permission_id IS NOT NULL) THEN 'covered'::text
            ELSE 'uncovered'::text
        END AS coverage_status,
    is_sensitive,
    requires_approval,
    rate_limit_per_hour,
    is_active
   FROM public.route_permissions
  ORDER BY route_path, http_method;


