    CONSTRAINT sales_opportunities_estimated_value_check CHECK (((estimated_value IS NULL) OR (estimated_value >= (0)::numeric))),
    CONSTRAINT sales_opportunities_probability_check CHECK (((probability IS NULL) OR ((probability >= 0) AND (probability <= 100)))),
    CONSTRAINT sales_opportunities_status_check CHECK (((status)::text = ANY (ARRAY[('open'::character varying)::text, ('qualified'::character varying)::text, ('proposal'::character varying)::text, ('negotiation'::character varying)::text, ('won'::character varying)::text, ('lost'::character varying)::text, ('abandoned'::character varying)::text])))
