--

CREATE TABLE public.sensitive_operation_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operation_id character varying(255) NOT NULL,
    operation_type character varying(100) NOT NULL,
    user_id character varying(255) NOT NULL,
    organization_id character varying(255) NOT NULL,
    table_affected character varying(100),
    record_id character varying(255),
    changes_json jsonb,
    restricted_fields_modified jsonb,
    requires_approval boolean DEFAULT false,
    approval_obtained boolean DEFAULT false,
    approver_id character varying(255),
    self_approval_risk boolean DEFAULT false,
    elevation_risk boolean DEFAULT false,
    idempotency_key character varying(255),
    is_replay boolean DEFAULT false,
    executed_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    status character varying(50),
    blocking_reason text
);


--
-- Name: TABLE sensitive_operation_audit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sensitive_operation_audit IS 'Complete audit trail of all sensitive operations with security events';


--
-- Name: sensitive_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sensitive_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operation_name character varying(255) NOT NULL,
    operation_type character varying(100),
    description text,
    requires_separate_approver boolean DEFAULT true,
    requires_two_factor_auth boolean DEFAULT false,
    requires_executive_approval boolean DEFAULT false,
    requires_audit_log boolean DEFAULT true,
    requires_idempotency_key boolean DEFAULT true,
    idempotency_window_seconds integer DEFAULT 3600,
    max_per_hour integer,
    max_per_day integer,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE sensitive_operations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sensitive_operations IS 'Define sensitive operations that require approval, replay prevention, and security checks';


--
-- Name: sensitive_operations_audit_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sensitive_operations_audit_summary AS
 SELECT operation_type,
    count(*) AS total_operations,
    count(
        CASE
            WHEN (requires_approval = true) THEN 1
            ELSE NULL::integer
        END) AS required_approvals,
    count(
        CASE
            WHEN (approval_obtained = true) THEN 1
            ELSE NULL::integer
        END) AS approved_operations,
    count(
        CASE
            WHEN (self_approval_risk = true) THEN 1
            ELSE NULL::integer
        END) AS self_approval_risks,
    count(
        CASE
            WHEN (elevation_risk = true) THEN 1
            ELSE NULL::integer
        END) AS elevation_risks,
    count(
        CASE
            WHEN (is_replay = true) THEN 1
            ELSE NULL::integer
        END) AS replay_attempts,
    max(executed_at) AS latest_operation
   FROM public.sensitive_operation_audit
  WHERE (executed_at >= (CURRENT_TIMESTAMP - '30 days'::interval))
  GROUP BY operation_type;


