    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id character varying(255) NOT NULL,
    anomaly_type character varying(100),
    severity_level character varying(50),
    detected_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    detection_confidence numeric(3,2),
    anomaly_description text,
    baseline_rps numeric(10,2),
    peak_rps numeric(10,2),
    spike_percentage integer,
    affected_endpoints jsonb,
    affected_regions jsonb,
    unique_ips_count integer,
    unique_users_count integer,
    request_patterns jsonb,
    user_agent_patterns jsonb,
    mitigation_started_at timestamp with time zone,
    mitigation_method character varying(100),
    mitigation_applied boolean DEFAULT false,
    traffic_restored_at timestamp with time zone,
    status character varying(50)
);


--
-- Name: TABLE traffic_anomaly_detection; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.traffic_anomaly_detection IS 'Detect and track traffic anomalies and DDoS attacks';


--
-- Name: traffic_anomaly_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.traffic_anomaly_summary AS
 SELECT organization_id,
    anomaly_type,
    count(*) AS total_anomalies,
    count(
        CASE
            WHEN ((status)::text = 'detected'::text) THEN 1
            ELSE NULL::integer
        END) AS active_anomalies,
    avg(spike_percentage) AS avg_spike_percentage,
    max(peak_rps) AS max_peak_rps,
    max(detected_at) AS most_recent_anomaly
   FROM public.traffic_anomaly_detection
  WHERE (detected_at >= (CURRENT_TIMESTAMP - '7 days'::interval))
  GROUP BY organization_id, anomaly_type;


