-- Name: TABLE user_role_assignments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.user_role_assignments IS 'Assign users to roles per organization with lifecycle tracking';


--
-- Name: user_effective_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_effective_permissions AS
 SELECT ura.user_id,
    ura.organization_id,
    rd.role_name,
    pd.permission_name,
    pd.category,
    rp.condition_type,
    rp.condition_metadata,
    ura.is_active,
    ura.assigned_at,
    ura.revoked_at
   FROM (((public.user_role_assignments ura
     JOIN public.role_definitions rd ON ((rd.id = ura.role_id)))
     JOIN public.role_permissions rp ON ((rp.role_id = rd.id)))
     JOIN public.permission_definitions pd ON ((pd.id = rp.permission_id)))
  WHERE ((ura.is_active = true) AND (rd.is_active = true))
  ORDER BY ura.user_id, ura.organization_id, rd.role_name;


