--

CREATE TABLE public.v1_certifications (
    id bigint NOT NULL,
    release_version text NOT NULL,
    source_commit text NOT NULL,
    architecture_verified boolean DEFAULT false NOT NULL,
    security_verified boolean DEFAULT false NOT NULL,
    data_integrity_verified boolean DEFAULT false NOT NULL,
    operations_verified boolean DEFAULT false NOT NULL,
    documentation_verified boolean DEFAULT false NOT NULL,
    compliance_verified boolean DEFAULT false NOT NULL,
    release_candidate_verified boolean DEFAULT false NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    decision text DEFAULT 'pending'::text NOT NULL,
    approved_by bigint,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT v1_certifications_decision_check CHECK ((decision = ANY (ARRAY['pending'::text, 'certified'::text, 'rejected'::text, 'revoked'::text])))
);


--
-- Name: v1_certifications_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.v1_certifications_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: v1_certifications_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.v1_certifications_id_seq OWNED BY public.v1_certifications.id;


